from collections import deque

def get_all_shapes(grid):
    shapes = []
    vis = [[False]*cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] >= 1 and not vis[r][c]:
                shape_cells = []
                Q = deque([(r,c)])
                vis[r][c] = True
                while Q:
                    cr, cc = Q.popleft()
                    shape_cells.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not vis[nr][nc] and grid[nr][nc] >= 1:
                                vis[nr][nc] = True
                                Q.append((nr, nc))
                shapes.append(shape_cells)
    return shapes

