# Let me implement the transformation correctly
def find_shapes(grid):
    """Return all 4-connected shapes of non-zero cells."""
    rows, cols = len(grid), len(grid[0])
    shapes = []
    vis = [[False]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] >= 1 and not vis[r][c]:
                cells = []
                q = [(r, c)]
                vis[r][c] = True
                while q:
                    cr, cc = q.pop(0)
                    cells.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols and not vis[nr][nc] and grid[nr][nc] >= 1:
                            vis[nr][nc] = True
                            q.append((nr, nc))
                shapes.append(cells)
    return shapes

def get_special_color(shape_cells, grid):
    """Get the special color value in this shape (max value >= 4)."""
    colors = [grid[r][c] for r, c in shape_cells if grid[r][c] >= 4]
    return max(colors) if colors else None

def get_square_cells(shape_cells_one):
    """Get all cells that are part of any 2x2 or 3x3 square of 1s."""
    squares = set()
    for n in [2, 3]:
        for r in range(rows - n + 1):
            for c in range(cols - n + 1):
                is_square = True
                for dr in range(n):
                    for dc in range(n):
                        if (r+dr, c+dc) not in shape_cells_one:
                            is_square = False
                            break
                if is_square:
                    for dr in range(n):
                        for dc in range(n):
                    squares.add((r+dr, c+dc))
